-- Independent expectations generated by running the original H5 function.
local M={}
local function Near(a,b) return math.abs(a-b)<.0001 end
function M.Check(p)
    local f=File('tools/migration/crater-source-animation.json',FILE_READ)
    local reference=cjson.decode(f:ReadString());f:Dispose()
    local env=p.environment
    local materials=require('core.ResourceData').Read('Crater/Materials.json');local strip=nil ---@type Material|nil
    for i,material in ipairs(materials) do if material.kind=='glow' then strip=cache:GetResource('Material','Crater/material-'..i..'.xml');break end end
    assert(strip,'authored glow material is required')
    V.assert(Near(strip.depthBias.slopeScaledBias,-2) and math.abs(strip.depthBias.constantBias+4/2^24)<1e-9,'source glow depth bias loads from authored material')
    local byName={};for _,d in ipairs(env.dynamics) do byName[d.node.name]=d.node end
    for _,sample in ipairs(reference.samples) do
        env.time=sample.time;env:Update(0,p.camera.node)
        for _,expected in ipairs(sample.nodes) do
            local n=assert(byName[expected.name]);local pos,rot,scale=n.position,n.rotation,n.scale
            local a,b,c=expected.p,expected.q,expected.s
            local dot=rot.x*b[1]-rot.y*b[2]-rot.z*b[3]+rot.w*b[4]
            V.assert(Near(pos.x,-a[1]) and Near(pos.y,a[2]) and Near(pos.z,a[3]) and math.abs(math.abs(dot)-1)<.00001
                and Near(scale.x,c[1]) and Near(scale.y,c[2]) and Near(scale.z,c[3]),'H5 pose '..expected.name..' t='..sample.time)
        end
    end
    local bases={fire={1.388326192033025*.3,.2000578015675927*.15,.019991901728717534*.09},breath={.5437318387139703,1.9099798011964528,2.56235552498022}}
    for _,g in ipairs(env.glows) do
        local base=bases[g.kind]
        if base then
            V.assert(Near(g.color[1],base[1]) and Near(g.color[2],base[2]) and Near(g.color[3],base[3]),'canonical '..g.kind..' emission, fire tint applied once')
            local linked=false
            for _,model in ipairs(p.scene:GetComponents('StaticModel',true)) do if model.material==g.material then linked=true;break end end
            V.assert(linked,'animated '..g.kind..' material bound to rendered model')
        end
    end
    env.time=10;env:Update(0,p.camera.node)
end
return M
